def preparar_contacto(apps, schema_editor):
    if schema_editor.connection.alias == 'central':
        apps.get_model('usuarios', 'Rol').objects.using('central').get_or_create(
            codigo='contacto', defaults={'nombre': 'Contacto', 'activo': True, 'es_sistema': True,
                'descripcion': 'Perfil exclusivo de contacto@smartstockchile.cl para atender su buzón.'})


def retirar_perfil_sin_usuarios(apps, schema_editor):
    if schema_editor.connection.alias == 'central':
        apps.get_model('usuarios', 'Rol').objects.using('central').filter(
            codigo='contacto', usuarios__isnull=True).delete()


